fast_pseudocode:
# restore_value prevents corruption; grid lambda enables autotune to expand grid
@triton.autotune(
    configs=[triton.Config({'XBLOCK': 1, 'R0_BLOCK': 8192}, ...), ...],
    key=['xnumel', 'r0_numel'],
    restore_value=['in_out_ptr0'],  # ADDED: restores tensor between benchmark trials
)
@triton.jit
def kernel(in_out_ptr0, ...):
    # pass 1: writes to in_out_ptr0
    # pass 2: reads from in_out_ptr0 (now safe)
    # pass 3: reads from in_out_ptr0 again

def launch():
    grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # dynamic grid
    kernel[grid](...)  # autotune selects XBLOCK/R0_BLOCK automatically

